create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', instrument text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.bands (id uuid primary key default gen_random_uuid(), name text not null, description text not null default '', invite_code text not null unique, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.band_members (band_id uuid not null references public.bands(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('ADMIN','MEMBER')) default 'MEMBER', created_at timestamptz not null default now(), primary key (band_id, user_id));
alter table public.profiles enable row level security; alter table public.bands enable row level security; alter table public.band_members enable row level security;
create or replace function public.is_band_member(target_band uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.band_members where band_id = target_band and user_id = auth.uid()); $$;
create or replace function public.is_band_admin(target_band uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.band_members where band_id = target_band and user_id = auth.uid() and role = 'ADMIN'); $$;
create policy "profiles own read" on public.profiles for select using (id = auth.uid()); create policy "profiles own insert" on public.profiles for insert with check (id = auth.uid()); create policy "profiles own update" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "members can read bands" on public.bands for select using (public.is_band_member(id)); create policy "authenticated can create bands" on public.bands for insert with check (created_by = auth.uid()); create policy "admins update bands" on public.bands for update using (public.is_band_admin(id)); create policy "admins delete bands" on public.bands for delete using (public.is_band_admin(id));
create policy "members read membership" on public.band_members for select using (public.is_band_member(band_id)); create policy "admins manage membership" on public.band_members for all using (public.is_band_admin(band_id));
create or replace function public.create_band(p_name text, p_description text default '') returns public.bands language plpgsql security definer set search_path = public as $$ declare b public.bands; code text; begin if auth.uid() is null then raise exception 'not authenticated'; end if; loop code := upper(substr(encode(gen_random_bytes(5), 'hex'), 1, 8)); exit when not exists(select 1 from public.bands where invite_code = code); end loop; insert into public.bands(name, description, invite_code, created_by) values(p_name, coalesce(p_description,''), code, auth.uid()) returning * into b; insert into public.band_members(band_id, user_id, role) values(b.id, auth.uid(), 'ADMIN'); return b; end; $$;
create or replace function public.join_band(p_invite_code text) returns public.band_members language plpgsql security definer set search_path = public as $$ declare b public.bands; m public.band_members; begin if auth.uid() is null then raise exception 'not authenticated'; end if; select * into b from public.bands where invite_code = upper(trim(p_invite_code)); if not found then raise exception 'invalid invite code'; end if; insert into public.band_members(band_id, user_id, role) values(b.id, auth.uid(), 'MEMBER') on conflict do nothing returning * into m; if m.band_id is null then select * into m from public.band_members where band_id=b.id and user_id=auth.uid(); end if; return m; end; $$;
grant execute on function public.create_band(text,text) to authenticated; grant execute on function public.join_band(text) to authenticated;
